// The Users & sign-in page against the PHP that prints it (plan §5 S1.3): `SecurityView::page()`,
// captured once on a pinned state.
//
// The oracle is `test/fixtures/php-security.json`, generated by `v4/scripts/gen-security-fixture.sh`
// from the real `modules/Auth/Views/SecurityView.php` (plus `Permissions`, `Icons`, `RoleAdmin`'s
// constant and the real `SettingsSchema` for the fields) with a `Page` stub — not by booting the app.
// The shell is not compared here: `page.ts` is pinned by the login golden test, and the stub's
// `start()`/`simpleHeader()`/`end()` print nothing.
//
// Byte identity is the point: the fixture catches a changed space run, a reordered attribute, a
// missing `required`, a help text that moved, and the clock — its timestamps are fixed UTC strings
// read in a fixed zone, so a page that formatted `last_login_at` differently would differ here.

import { describe, expect, it } from "vitest";
import { formatTime, roleSummary, securityPage } from "../../src/html/security-view";
import fixture from "../fixtures/php-security.json";
import { TEST_PAGE } from "../helpers/page";
import { SECURITY_PERMISSIONS, SECURITY_ROLES, SECURITY_STATE } from "../helpers/security-state";

const PAGES = fixture.pages.security;

/** The `<main>` fragment: everything the fixture captured. */
const span = (html: string): string => {
	const start = html.indexOf("<main");
	const end = html.indexOf("</main>");
	return html.slice(start, end + "</main>".length);
};

/** The token the generator's stub `csrf()` returns, so no normalisation is needed on either side. */
const settings = { ...TEST_PAGE, csrf: PAGES.csrf };

describe("/settings/security is the page v3 renders", () => {
	it("prints the section PHP prints, byte for byte", () => {
		expect(span(securityPage(settings, SECURITY_STATE))).toBe(PAGES.body);
	});

	it("prints the re-render after a refused write, with the message under Users", () => {
		const html = securityPage(settings, SECURITY_STATE, {
			users: "The user name \u201cadmin\u201d is taken.",
		});
		expect(span(html)).toBe(PAGES.usersErrorBody);
	});

	it("wraps it in the page shell, with the title and body class the PHP view asks for", () => {
		const html = securityPage(settings, SECURITY_STATE);
		expect(html).toContain("<title>Users &amp; sign-in \u00b7 Settings \u00b7 Apotheke</title>");
		expect(html).toContain('<body class="page-settings">');
	});

	it("prints the toast after the section when one is asked for", () => {
		const html = securityPage(settings, SECURITY_STATE, {}, "User added");
		expect(html).toContain('</main>\n<div class="toast" role="status">User added</div>');
	});
});

describe("the page's own formatting", () => {
	it("reads a stored UTC time in the app's zone, with v3's format", () => {
		// `2026-01-02 03:04:05Z` in Europe/Athens is 05:04 the same day; `H:i` is the time format.
		expect(formatTime("2026-01-02 03:04:05", "H:i", "Europe/Athens")).toBe("2 Jan 2026, 05:04");
		expect(formatTime("2026-01-02 03:04:05", "g:i A", "UTC")).toBe("2 Jan 2026, 3:04 AM");
		// A DST boundary: 01:30 UTC on 29 March 2026 is 04:30 in Athens (the clocks moved at 03:00).
		expect(formatTime("2026-03-29 01:30:00", "H:i", "Europe/Athens")).toBe("29 Mar 2026, 04:30");
		// A stored value that is not a time is printed as it is, as PHP's `catch` does.
		expect(formatTime("not-a-time", "H:i", "UTC")).toBe("not-a-time");
	});

	it("summarises a role in v3's words: admin everything, no permissions nothing", () => {
		expect(roleSummary("admin", SECURITY_ROLES, SECURITY_PERMISSIONS)).toBe("everything");
		expect(roleSummary("viewer", SECURITY_ROLES, SECURITY_PERMISSIONS)).toBe("view, export, labels, backup");
		expect(roleSummary("ghost", SECURITY_ROLES, SECURITY_PERMISSIONS)).toBe("nothing");
	});
});
